column7:
{
    "type": "object",
    "properties": {
        "operation": {
            "type": "string",
            "description": "操作类型，可选值：提高、降低、打开、关闭、设置、查询等"
        },
        "object": {
            "type": "string",
            "description": "控制对象，如静音、音量",
            "enum": [
                "静音",
                "音量"
            ]
        },
        "value": {
            "type": "string",
            "description": "音量值，如数字（30）、百分比（50%）、倍数（1.5倍）；静音操作时为空"
        },
        "date_time": {
            "type": "string",
            "description": "定时时间，当前工具不使用"
        },
        "device": {
            "type": "string",
            "description": "设备标识，当前工具不使用"
        },
        "location": {
            "type": "string",
            "description": "位置标识，当前工具不使用"
        }
    },
    "required": [
        "operation",
        "object"
    ]
}

column8:
{
    "$schema": "http://json-schema.org/draft-04/schema#",
    "type": "object",
    "properties": {
        "type": "object",
        "properties": {
            "code": {
                "type": "string",
                "description": "返回状态码"
            },
            "message": {
                "type": "string",
                "description": "接口返回状态描述"
            },
            "data": {
                "type": "object",
                "properties": {
                    "sort": {
                        "type": "string",
                        "description": "业务分类，相同的UI下发sort相同。\nsort=tvcontrol"
                    },
                    "subsort": {
                        "type": "string",
                        "description": "技能子分类。subsort=tvcontrol"
                    },
                    "data": {
                        "type": "object",
                        "properties": {
                            "keyCode": {
                                "type": "number",
                                "description": "实现模块标识"
                            },
                            "keyValue": {
                                "type": "number",
                                "description": "相同实现模块对应的不同指令值"
                            },
                            "keyOffset": {
                                "type": "number",
                                "description": "指令调整值"
                            },
                            "keyPara1": {
                                "type": "string",
                                "description": "相同实现模块对应的相同指令值的不同模块"
                            },
                            "cmdWord": {
                                "type": "string",
                                "description": "控制基准指令，多意图使用"
                            },
                            "executeFlag": {
                                "type": "number",
                                "description": "默认为1"
                            },
                            "showText": {
                                "type": "string",
                                "description": "展示文本"
                            },
                            "action": {
                                "type": "string",
                                "description": "实现模块的action"
                            },
                            "needPlayTTS": {
                                "type": "string",
                                "description": "是否需要终端播报，1代表需要播报"
                            }
                        },
                        "description": "电视控制核心数据",
                        "required": [
                            "keyPara1",
                            "keyCode",
                            "keyValue",
                            "executeFlag",
                            "showText",
                            "action",
                            "keyOffset",
                            "needPlayTTS",
                            "cmdWord"
                        ]
                    },
                    "ttscontent": {
                        "type": "string",
                        "description": "播报语"
                    },
                    "ttsReplace": {
                        "type": "string",
                        "description": "是否使用趣味播报标识，ttsReplace等于0，禁止重写或覆盖",
                        "enum": [
                            "0",
                            "1",
                            "2"
                        ]
                    },
                    "screenOper": {
                        "type": "string",
                        "description": "1、参数说明：开关屏的参数。 2、参数值的说明： 1）1：终端执行开屏； 2）0：终端执行关屏； 3）3：终端需要特殊逻辑处理（如打开声纹）。"
                    },
                    "priority": {
                        "type": "string",
                        "description": "1、用于终端，是否优先级处理界面词。解决的问题多轮场景，会误进界面词的情况。",
                        "enum": [
                            "uicommand",
                            "nlpresult"
                        ]
                    },
                    "multiresult": {
                        "type": "string",
                        "description": "多轮信息（dialog，下轮nlu使用）"
                    },
                    "multiSpeech": {
                        "type": "string",
                        "description": "设置免唤醒打开，1代表激活多轮免唤醒"
                    },
                    "fullDuplex": {
                        "type": "string",
                        "description": "全双工"
                    },
                    "dataconfidence": {
                        "type": "string",
                        "description": "置信度"
                    },
                    "debugLog": {
                        "type": "object",
                        "properties": {},
                        "description": "调试信息"
                    },
                    "llmSemantic": {
                        "type": "object",
                        "properties": {
                            "domain": {
                                "type": "string",
                                "description": "领域"
                            },
                            "intent": {
                                "type": "string",
                                "description": "意图"
                            }
                        },
                        "required": [
                            "domain",
                            "intent"
                        ],
                        "description": "大模型参数"
                    }
                },
                "required": [
                    "sort",
                    "subsort",
                    "ttscontent",
                    "ttsReplace",
                    "screenOper",
                    "priority",
                    "multiresult",
                    "multiSpeech",
                    "fullDuplex",
                    "debugLog",
                    "llmSemantic",
                    "data"
                ]
            }
        },
        "required": [
            "code",
            "message",
            "data"
        ]
    },
    "required": []
}

