{
    "type": "object",
    "properties": {
        "operation": {
            "type": "string",
            "description": "操作类型，可选值：打开、关闭、查询",
            "enum": [
                "打开",
                "关闭",
                "查询"
            ]
        },
        "object": {
            "type": "string",
            "description": "控制对象，如开机、关机、重启、待机、睡眠、显示待机、剩余关机时长等"
        },
        "value": {
            "type": "string",
            "description": "控制值，当前工具通常为空"
        },
        "date_time": {
            "type": "string",
            "description": "定时关机的时间设定，如30分钟、1小时、120分钟、定时时间点（20:00）、时间段（22:00-06:00）、定时"
        },
        "device": {
            "type": "string",
            "description": "设备标识，当前工具不使用"
        },
        "location": {
            "type": "string",
            "description": "位置标识，当前工具不使用"
        }
    },
    "required": [
        "operation",
        "object"
    ]
}

